const _sfc_main$u = {
  name: 'Login',
  data() {
    return {
      formData: {
        email: '',
        password: '',
        remember: false
      },
      showPassword: false,
      isLoading: false
    };
  },
  methods: {
    async handleLogin() {
      this.isLoading = true;
      
      setTimeout(() => {
        if (this.formData.email && this.formData.password) {
          localStorage.setItem('isAuthenticated', 'true');
          localStorage.setItem('userEmail', this.formData.email);
          this.$router.push('/dashboard');
        }
        
        this.isLoading = false;
      }, 1500);
    }
  }
};

