const _sfc_main$n = {
  name: 'Suppliers',
  data() {
    return {
      fournisseurs: [],
      loading: true,
      saving: false,
      showModal: false,
      isEditing: false,
      editingId: null,
      searchQuery: '',
      searchTimeout: null,
      errorMessage: '',
      newCommercial: '',
      pagination: {
        current_page: 1,
        last_page: 1,
        total: 0
      },
      form: this.getEmptyForm()
    };
  },
  mounted() {
    this.fetchFournisseurs();
  },
  methods: {
    getEmptyForm() {
      return {
        nom: '',
        nom_alternatif: '',
        code_client: '',
        code_fournisseur: '',
        etat: 'Ouvert',
        adresse: '',
        code_postal: '',
        ville: '',
        pays: 'Maroc (MA)',
        departement: '',
        telephone: '',
        tel_portable: '',
        fax: '',
        web: '',
        email: '',
        id_prof_1_rc: '',
        id_prof_2_patente: '',
        id_prof_3_if: '',
        id_prof_4_cnss: '',
        ice: '',
        assujetti_tva: true,
        numero_tva: '',
        type_tiers: 'Fournisseur',
        effectifs: '',
        type_entite_legale: '',
        capital: null,
        devise_capital: 'MAD',
        conditions_reglement: '',
        mode_reglement: '',
        maison_mere: '',
        commerciaux: [],
        logo: null,
        categorie: 'local',
        devise: 'MAD',
        eori: ''
      };
    },
    async fetchFournisseurs(page = 1) {
      this.loading = true;
      try {
        const params = { page };
        if (this.searchQuery) {
          params.search = this.searchQuery;
        }
        const response = await axios.get('/api/fournisseurs', { params });
        this.fournisseurs = response.data.data;
        this.pagination = {
          current_page: response.data.current_page,
          last_page: response.data.last_page,
          total: response.data.total
        };
      } catch (error) {
        console.error('Error fetching fournisseurs:', error);
      } finally {
        this.loading = false;
      }
    },
    debouncedSearch() {
      clearTimeout(this.searchTimeout);
      this.searchTimeout = setTimeout(() => {
        this.fetchFournisseurs(1);
      }, 300);
    },
    changePage(page) {
      if (page >= 1 && page <= this.pagination.last_page) {
        this.fetchFournisseurs(page);
      }
    },
    openModal(fournisseur = null) {
      this.errorMessage = '';
      if (fournisseur) {
        this.isEditing = true;
        this.editingId = fournisseur.id;
        this.form = { ...this.getEmptyForm(), ...fournisseur };
        if (typeof this.form.commerciaux === 'string') {
          this.form.commerciaux = this.form.commerciaux ? this.form.commerciaux.split(',') : [];
        }
      } else {
        this.isEditing = false;
        this.editingId = null;
        this.form = this.getEmptyForm();
      }
      this.showModal = true;
    },
    closeModal() {
      this.showModal = false;
      this.errorMessage = '';
    },
    addCommercial() {
      if (this.newCommercial.trim()) {
        if (!this.form.commerciaux) {
          this.form.commerciaux = [];
        }
        this.form.commerciaux.push(this.newCommercial.trim());
        this.newCommercial = '';
      }
    },
    removeCommercial(index) {
      this.form.commerciaux.splice(index, 1);
    },
    handleLogoUpload(event) {
      const file = event.target.files[0];
      if (file) {
        this.form.logo = file;
      }
    },
    async saveFournisseur() {
      this.saving = true;
      this.errorMessage = '';
      try {
        const formData = {
          ...this.form,
          commerciaux: Array.isArray(this.form.commerciaux) ? this.form.commerciaux.join(',') : this.form.commerciaux
        };
        
        if (this.isEditing) {
          await axios.put(`/api/fournisseurs/${this.editingId}`, formData);
        } else {
          await axios.post('/api/fournisseurs', formData);
        }
        this.closeModal();
        this.fetchFournisseurs(this.pagination.current_page);
      } catch (error) {
        if (error.response && error.response.data && error.response.data.errors) {
          const errors = error.response.data.errors;
          this.errorMessage = Object.values(errors).flat().join(', ');
        } else {
          this.errorMessage = 'Une erreur est survenue. Veuillez réessayer.';
        }
      } finally {
        this.saving = false;
      }
    },
    async deleteFournisseur(id) {
      if (confirm('Êtes-vous sûr de vouloir supprimer ce fournisseur ?')) {
        try {
          await axios.delete(`/api/fournisseurs/${id}`);
          this.fetchFournisseurs(this.pagination.current_page);
        } catch (error) {
          console.error('Error deleting fournisseur:', error);
          alert('Erreur lors de la suppression du fournisseur');
        }
      }
    },
    getInitials(name) {
      if (!name) return '?';
      return name
        .split(' ')
        .map(word => word.charAt(0))
        .join('')
        .toUpperCase()
        .substring(0, 2);
    }
  }
};

